#include "providers/mock/MockProvider.hpp"
#include <algorithm>
namespace airmuse { class MockProvider::Session final:public IMediaSession { public: Session(MockProvider&o,MediaSnapshot s):owner(o),snapshot(std::move(s)){} SessionId Id()const override{return snapshot.sessionId;} MediaSnapshot GetSnapshot()const override{return snapshot;} ProviderCapabilities GetCapabilities()const override{return snapshot.capabilities;} Result<void> Play()override{return Change(PlaybackStatus::Playing);} Result<void> Pause()override{return Change(PlaybackStatus::Paused);} Result<void> Next()override{return Result<void>::Ok();} Result<void> Previous()override{return Result<void>::Ok();} Result<void> SeekTo(Milliseconds p)override{snapshot.position=p;++snapshot.revision;snapshot.updatedAt=std::chrono::steady_clock::now();owner.Emit({MediaEvent::Kind::SnapshotChanged,snapshot.providerId,snapshot.sessionId,snapshot,{}});return Result<void>::Ok();} private:Result<void> Change(PlaybackStatus s){snapshot.status=s;++snapshot.revision;snapshot.updatedAt=std::chrono::steady_clock::now();owner.Emit({MediaEvent::Kind::SnapshotChanged,snapshot.providerId,snapshot.sessionId,snapshot,{}});return Result<void>::Ok();} MockProvider&owner;MediaSnapshot snapshot;};
MockProvider::MockProvider(ProviderId id):id_(std::move(id)){} ProviderId MockProvider::Id()const{return id_;} ProviderStatus MockProvider::GetStatus()const{return status_;} ProviderCapabilities MockProvider::GetCapabilities()const{return {true,true,true,true,true,true,true,true};} std::vector<std::shared_ptr<IMediaSession>> MockProvider::GetSessions()const{std::lock_guard l(mutex_);std::vector<std::shared_ptr<IMediaSession>> out;for(auto&s:sessions_)out.push_back(s);return out;} Result<void> MockProvider::Initialize(){status_=ProviderStatus::Ready;return Result<void>::Ok();} void MockProvider::Shutdown(){status_=ProviderStatus::Offline;} Subscription MockProvider::Subscribe(EventBus::Callback cb){return events_.Subscribe(std::move(cb));} void MockProvider::Emit(MediaEvent e){events_.Publish(e);} void MockProvider::AddSession(MediaSnapshot s){s.providerId=id_;std::lock_guard l(mutex_);auto session=std::make_shared<Session>(*this,s);sessions_.push_back(session);Emit({MediaEvent::Kind::SessionDiscovered,id_,s.sessionId,s,{}});} void MockProvider::Disconnect(){status_=ProviderStatus::Offline;Emit({MediaEvent::Kind::ProviderDisconnected,id_,{}, {},"mock disconnect"});} }
